// ---- Services ----

/** Maintenance is the bound service of the 维护 page. */
export const Maintenance = {
  /** Catalog returns the maintenance tasks of this platform in display order. */
  catalog(): Promise<TaskView[]> {
    return call("Maintenance.Catalog");
  },
  /** Run runs the tasks named by ids, streams progress, records the run in the history and returns its summary. It fails without running anything when ids is empty, names an unknown task, or another run is in progress; the error's text is a sentence in Simplified Chinese for the page to show, and the engine's own error goes to the log. Admin tasks run together behind one system prompt. */
  run(ids: string[], progress: Channel<ProgressEvent>): Promise<RunSummary> {
    return call("Maintenance.Run", ids, progress);
  },
} as const;

/** Health is the bound service behind the CPU alert banner. */
export const Health = {
  /** Alerts returns the current alerts, most CPU first; the page calls it once and then follows events.healthAlerts. */
  alerts(): Promise<Alert[]> {
    return call("Health.Alerts");
  },
  /** OpenSystemMonitor opens Activity Monitor on macOS or Task Manager on Windows, for 查看详情 until the 健康监测 page exists. */
  openSystemMonitor(): Promise<void> {
    return call("Health.OpenSystemMonitor");
  },
} as const;

/** History is the bound service of the 操作历史 page. */
export const History = {
  /** Clear deletes every recorded run. It cannot be undone; the page confirms first. */
  clear(): Promise<void> {
    return call("History.Clear");
  },
  /** List returns up to limit recorded runs, newest first; limit must be between 1 and history.MaxRuns. */
  list(limit: number): Promise<Run[]> {
    return call("History.List", limit);
  },
} as const;

/** Permissions is the bound service for system permissions, backed by mygo's permissionflow plugin. It also implements maintenance.PermissionChecker for the engine. */
export const Permissions = {
  /** FullDiskAccess reports whether the app has Full Disk Access (macOS), which the 优化应用数据库 task needs to reach Safari's and Mail's databases. Windows has no such permission: "notRequired". */
  fullDiskAccess(): Promise<PermissionState> {
    return call("Permissions.FullDiskAccess");
  },
  /** GuideFullDiskAccess opens System Settings at Full Disk Access with a panel showing the app to drag into the list, and returns once the user granted it, closed the panel or System Settings, or the page went away. */
  guideFullDiskAccess(): Promise<PermissionState> {
    return call("Permissions.GuideFullDiskAccess");
  },
} as const;

/** Settings is the bound service of the 设置 page. */
export const Settings = {
  /** About returns the app's version and its data folder. */
  about(): Promise<AppAbout> {
    return call("Settings.About");
  },
  /** ChooseFolder shows the system's folder picker titled title and returns the folder the user chose, or "" when they cancelled. It does not change the settings: the page adds the folder to a list and calls Update. */
  chooseFolder(title: string): Promise<string> {
    return call("Settings.ChooseFolder", title);
  },
  /** Get returns the current settings. General.LaunchAtLogin reports the system's state, which the user can also change in System Settings or Task Manager. */
  get(): Promise<AppSettings> {
    return call("Settings.Get");
  },
  /** Limits returns the ranges Update clamps to. */
  limits(): Promise<SettingsLimits> {
    return call("Settings.Limits");
  },
  /** Reset restores every default, including turning off 登录时启动. */
  reset(): Promise<AppSettings> {
    return call("Settings.Reset");
  },
  /** Update stores next after clamping it to the allowed ranges (see the settings package) and returns what was stored, which the page shows instead of what it sent. Every window then receives events.settingsChanged. */
  update(next: AppSettings): Promise<AppSettings> {
    return call("Settings.Update", next);
  },
} as const;

/** Files is the bound service for single files and the Trash, shared by every page. */
export const Files = {
  /** EmptyTrash deletes everything in the Trash for good and returns what it freed. It cannot be undone; the page confirms first. */
  emptyTrash(): Promise<TrashUsage> {
    return call("Files.EmptyTrash");
  },
  /** Reveal shows path selected in Finder or Explorer. */
  reveal(path: string): Promise<void> {
    return call("Files.Reveal", path);
  },
  /** TrashSize returns how much the Trash (Recycle Bin) holds. */
  trashSize(): Promise<TrashUsage> {
    return call("Files.TrashSize");
  },
} as const;

/** Cleanup is the bound service every cleaner page scans and cleans through, by CleanerID. It records each clean in the history. */
export const Cleanup = {
  /** Available lists the cleaners that are wired up, sorted. */
  available(): Promise<CleanerID[]> {
    return call("Cleanup.Available");
  },
  /** Clean deletes what req names from cleaner's last scan, streams progress, records the clean in the history and returns what it did. It fails without deleting anything when the request does not match the last scan (the page then scans again). Closing the channel stops the clean after the current item; the result says it was interrupted. */
  clean(cleaner: CleanerID, req: CleanRequest, progress: Channel<Progress>): Promise<CleanResult> {
    return call("Cleanup.Clean", cleaner, req, progress);
  },
  /** Scan runs the scan of cleaner, streams its progress and returns what it found; the cleaner remembers the result for Clean. Closing the channel cancels the scan. Errors are sentences in Simplified Chinese. */
  scan(cleaner: CleanerID, progress: Channel<Progress>): Promise<ScanResult> {
    return call("Cleanup.Scan", cleaner, progress);
  },
} as const;

/** Uninstall is the bound service of the 应用卸载 page: list → pick → leftovers → remove. It records each removal in the history. */
export const Uninstall = {
  /** Apps lists the installed apps, sorted by name, without their sizes, icons and last use (Measure streams those). */
  apps(): Promise<UninstallApp[]> {
    return call("Uninstall.Apps");
  },
  /** CheckRemoved checks again whether a Windows program is gone, for an uninstaller that went on after the process Spruce started exited. */
  checkRemoved(appID: string): Promise<UninstallerOutcome> {
    return call("Uninstall.CheckRemoved", appID);
  },
  /** Leftovers finds what the app left in the user's folders and measures it with the app; the result is what Remove picks from. On Windows it answers only after the program's uninstaller removed it. */
  leftovers(appID: string): Promise<UninstallPlan> {
    return call("Uninstall.Leftovers", appID);
  },
  /** Measure streams the size, icon and last use of every app of the last Apps call as each becomes known, and returns when all are measured. Closing the channel stops it. */
  measure(details: Channel<UninstallAppDetails>): Promise<void> {
    return call("Uninstall.Measure", details);
  },
  /** Remove moves the planned app (macOS) and the chosen leftovers to the Trash, streams progress and records the removal in the history. The app goes first; when it cannot be moved its leftovers stay too and BundleFailure says why. Closing the channel stops after the current item. */
  remove(req: UninstallRequest, progress: Channel<Progress>): Promise<UninstallOutcome> {
    return call("Uninstall.Remove", req, progress);
  },
  /** RunUninstaller runs a Windows program's own uninstaller, so its UI and the UAC prompt appear, sends one status once it runs, waits for it to exit and checks whether the program is gone; closing the channel stops the wait (never the uninstaller). The run is recorded in the history. */
  runUninstaller(appID: string, status: Channel<UninstallerStatus>): Promise<UninstallerOutcome> {
    return call("Uninstall.RunUninstaller", appID, status);
  },
} as const;

/** Space is the bound service of the 空间透视 page. It keeps the last scan's tree, so the page opens one folder at a time without scanning again; moving an entry to the Trash corrects the sizes above it in place. */
export const Space = {
  /** Children returns the folder id of the scan scanID with its children, largest first, and the folders above it. */
  children(scanID: string, id: number): Promise<SpaceListing> {
    return call("Space.Children", scanID, id);
  },
  /** ChooseFolder shows the system's folder picker over the calling window and returns the chosen folder, or "" when the user cancelled. */
  chooseFolder(): Promise<string> {
    return call("Space.ChooseFolder");
  },
  /** Current returns the last scan, or null before the first, so the page can show it again without scanning. */
  current(): Promise<SpaceSummary | null> {
    return call("Space.Current");
  },
  /** LargeFiles returns the largest files of the scan scanID (up to 200, from LargeFileMin up), largest first. */
  largeFiles(scanID: string): Promise<SpaceEntry[]> {
    return call("Space.LargeFiles", scanID);
  },
  /** Locations returns the disks and folders the start screen offers. A disk list the system cannot give is logged and left empty; the folders are still offered. */
  locations(): Promise<SpaceLocations> {
    return call("Space.Locations");
  },
  /** Scan walks the folder at path (a disk's path from Locations scans the whole disk), streams progress and keeps the result for children, largeFiles and trash, replacing the previous scan. Closing the channel cancels the scan; the previous result then stays. Errors are sentences in Simplified Chinese. */
  scan(path: string, progress: Channel<SpaceProgress>): Promise<SpaceSummary> {
    return call("Space.Scan", path, progress);
  },
  /** Trash moves the entries at paths of the scan scanID to the Trash (Recycle Bin), never deleting anything for good, corrects the sizes above them, records the move in the history and returns what it did. Only entries the scan found are moved, and only where space.Guard allows it (inside the home folder or the scanned folder, not a system location, not excluded in the settings); an entry that changed since the scan is left in place. */
  trash(scanID: string, paths: string[]): Promise<SpaceTrashResult> {
    return call("Space.Trash", scanID, paths);
  },
} as const;

/**
 * Sysinfo is the bound service behind the 健康监测 dashboard. The CPU alert on the same page comes from Health.
 *
 * Bound API (TypeScript view):
 *
 * 	Sysinfo.info(): Promise<SystemInfo>
 * 	Sysinfo.watch(samples: Channel<Vitals>): Promise<void>
 */
export const Sysinfo = {
  /** Info returns what does not change while the app runs: the OS, the model, the CPU and its cores, and the boot time. Fields that could not be read are empty. */
  info(): Promise<SystemInfo> {
    return call("Sysinfo.Info");
  },
  /** Watch streams the machine's vitals to the page: first the samples kept from the last two minutes (oldest first), then a new one every two seconds, until the page closes the channel or goes away. Sampling runs only while at least one page watches. */
  watch(samples: Channel<Vitals>): Promise<void> {
    return call("Sysinfo.Watch", samples);
  },
} as const;

// ---- Events ----

/** Events sent by the Go side. Subscribe with `events.name.on(listener)`. */
export const events = {
  /** HealthAlerts carries the complete current alert list to every window whenever it changes; an empty list clears the banner. */
  healthAlerts: event<Alert[]>("health:alerts"),
  /** HistoryAppended carries each run the history records, from any page or from Go, to every window, so 操作历史 shows it without being reopened. */
  historyAppended: event<Run>("history:appended"),
  /** SettingsChanged carries the complete settings to every window whenever they change, from any window or from Go. */
  settingsChanged: event<AppSettings>("settings:changed"),
} as const;
